41	/**
42	 * VarCodeGen stores necessary information about a (local) variable
43	 * and generates code for references to that variable.
44	 */
45	public abstract class VarCodeGen {
46	    protected final String name;
47	    public final Type fortressType;
48	    public final int sizeOnStack;
49	
50	    public VarCodeGen(String name, Type fortressType) {
51	        super();
52	        this.name = name;
53	        this.fortressType = fortressType;
54	        // TODO: compute sizeOnStack correctly for non-pointer types.
55	        this.sizeOnStack = 1;
56	    }
57	
58	    public static String varCGName(IdOrOp nm, List<StaticArg> lsargs) {
59	        return NamingCzar.idOrOpToString(nm) +
60	            (lsargs != null && lsargs.size() > 0 ? lsargs.toString() : "");
61	    }
62	    
63	    public VarCodeGen(IdOrOp name, List<StaticArg> lsargs, Type fortressType) {
64	        this(varCGName(name, lsargs), fortressType);
65	    }
66	
67	    public VarCodeGen(IdOrOp name, Type fortressType) {
68	        this(name.getText(), fortressType);
69	    }
70	
71	    public String getName() {
72	        return name;
73	    }
74	    
75	    public String toString() {
76	        return "VarCodeGen[] " + name + ":" + fortressType;
77	    }
78	
79	    public boolean isAMutableLocalVar() {
80	        if (this instanceof LocalMutableVar) return true; else return false;
81	    }
82	
83	    public boolean isAMutableTaskVar() {
84	        if (this instanceof MutableTaskVarCodeGen) return true; else return false;
85	    }
86	
87	    /** Generate code to push the value of this variable onto the Java stack.
88	     */
89	    public abstract void pushValue(CodeGenMethodVisitor mv);
90	
91	    public void pushValue(CodeGenMethodVisitor mv, String static_args) {
92	        if (static_args.length() == 0)
93	            pushValue(mv);
94	        else
95	            throw new CompilerError(errorMsg("Unexpected static args supplied to " + name +", statics = " + static_args));
96	    }
97	
98	    public void assignHandle(CodeGenMethodVisitor mv) {
99	        assignValue(mv);
100	    }
101	
102	    public void pushHandle(CodeGenMethodVisitor mv) {
103	        pushValue(mv);
104	    }
105	
106	    /** Generate code to assign the value of this variable from the
107	     *  top of the Java stack. */
108	    public abstract void assignValue(CodeGenMethodVisitor mv);
109	
110	    /** Generate metadata after last reference to this variable. */
111	    public abstract void outOfScope(CodeGenMethodVisitor mv);
