117	    public static abstract class StackVar extends VarCodeGen {
118	        protected final int offset;
119	
120	        protected StackVar(IdOrOp name, Type fortressType, CodeGen cg) {

120	        protected StackVar(IdOrOp name, Type fortressType, CodeGen cg) {
121	            super(name, fortressType);
122	            String tyDesc = null;
123	            if (fortressType != null) {
124	                tyDesc = NamingCzar.jvmTypeDesc(fortressType, cg.thisApi(), true, true);
125	            }
126	            this.offset = cg.mv.createCompilerLocal(name.getText(), tyDesc);
127	        }
128	
129	        public void pushValue(CodeGenMethodVisitor mv) {
130	            mv.visitVarInsn(Opcodes.ALOAD, offset);
131	        }
132	
133	        public void assignValue(CodeGenMethodVisitor mv) {
134	            mv.visitVarInsn(Opcodes.ASTORE, offset);
135	        }
136	
137	
138	        public void outOfScope(CodeGenMethodVisitor mv) {
139	            mv.disposeCompilerLocal(offset);
140	        }
141	
142	        public String toString() {
143	            return "VarCodeGen[StackVar] " + name + ":" + fortressType;
144	        }
145	    }
