207	
208	        public void assignValue(CodeGenMethodVisitor mv) {
209	            // URG, another case of meeting assumptions.
210	            // We get here with the value to assign on the stack, but not the 
211	            // object, so load the object, and then swap them, and add a return val
212	            // to keep the rest of codegen happy.
213	            mv.visitVarInsn(Opcodes.ALOAD,0);
214	            mv.visitInsn(Opcodes.SWAP);
215	            mv.visitFieldInsn(Opcodes.PUTFIELD, packageAndClassName, objectFieldName, classDesc);
216	            //            mv.visitMethodInsn(Opcodes.INVOKESTATIC, NamingCzar.internalFortressVoid, NamingCzar.make,
217	            //                               Naming.makeMethodDesc("", NamingCzar.descFortressVoid));
218	        }
