233	    public static class StaticBinding extends NeedsType {
234	
235	        List<String> sparams;
236	
237	        private StaticBinding(IdOrOp id, Type fortressType, String owner, String name, String desc, List<String> sparams) {
238	            super(id, fortressType, owner, name, desc);
239	            this.sparams = sparams;
240	        }
241	
242	        public StaticBinding(IdOrOp id, Type fortressType, String owner, String name, String desc) {
243	            super(id, fortressType, owner, name, desc);
244	            this.sparams = Collections.emptyList();
245	        }
246	
247	        public StaticBinding(IdOrOp id, List<StaticArg> lsargs, Type fortressType, String owner, String name, String desc) {
248	            super(id, lsargs, fortressType, owner, name, desc);
249	            this.sparams = Collections.emptyList();
250	        }
251	
252	        public void pushValue(CodeGenMethodVisitor mv) {
253	            mv.visitFieldInsn(Opcodes.GETSTATIC, packageAndClassName, objectFieldName, classDesc);
254	        }
255	
256	        public void pushValue(CodeGenMethodVisitor mv, String static_args) {
257	            String cd = classDesc;
258	
259	            if (static_args.length() > 0) {
260	                // need to rewrite the classDesc given static args.
261	                ArrayList<String> sargs = new ArrayList<String>();
262	                InstantiationMap.canonicalizeStaticParameters(static_args,
263	                                                              static_args.indexOf(Naming.LEFT_OXFORD),
264	                                                              static_args.lastIndexOf(Naming.RIGHT_OXFORD),
265	                                                              sargs);
266	
267	                Map<String, String> xlation  = Useful.map(sparams, sargs);
268	
269	                InstantiationMap im = new InstantiationMap(xlation);
270	
271	                cd = im.getUnmangledTypeDesc(cd);
272	
273	            }
274	
275	            // TODO work in progress.
276	            mv.visitFieldInsn(Opcodes.GETSTATIC, packageAndClassName+static_args, objectFieldName, cd);
277	        }
278	
279	        public void assignValue(CodeGenMethodVisitor mv) {
280	            throw new CompilerError(errorMsg("Invalid assignment to static binding ",name,
281	                    ": ", fortressType));
282	        }
283	
284	        public String toString() {
285	            return "VarCodeGen[StaticBinding] " + name + ":" + fortressType;
286	        }
287	
288	
289	        @Override
290	        public void outOfScope(CodeGenMethodVisitor mv) {
291	            // never happens
292	        }
293	
