296	    /** A mutable variable declared at the top level of a component.  Like
297	     * StaticBinding it lives in the singleton field of its own inner class,
298	     * but that field is not final, so it can be written after the class's
299	     * <clinit> has run.  A separate class rather than a flag on StaticBinding,
300	     * so that assignment to an immutable top-level variable keeps failing.
301	     */
302	    public static class MutableStaticBinding extends NeedsType {
303	
304	        public MutableStaticBinding(IdOrOp id, Type fortressType, String owner, String name, String desc) {
305	            super(id, fortressType, owner, name, desc);
306	        }
307	
308	        public void pushValue(CodeGenMethodVisitor mv) {
309	            mv.visitFieldInsn(Opcodes.GETSTATIC, packageAndClassName, objectFieldName, classDesc);
310	        }
311	
312	        public void assignValue(CodeGenMethodVisitor mv) {
313	            // The value to assign is already on the stack.
314	            mv.visitFieldInsn(Opcodes.PUTSTATIC, packageAndClassName, objectFieldName, classDesc);
315	        }
316	
317	        public String toString() {
318	            return "VarCodeGen[MutableStaticBinding] " + name + ":" + fortressType;
319	        }
320	
321	        @Override
322	        public void outOfScope(CodeGenMethodVisitor mv) {
323	            // never happens
324	        }
325	
326	    }
