352	    /** Local variable not visible outside current activation.  We
353	     *  don't presently distinguish mutable and immutable locals;
354	     *  perhaps we should.  A LocalVar doesn't include any variable
355	     *  that might scope over a local lambda, local object
356	     *  declaration, across work items, etc.  Those will require
357	     *  separate subclasses, which is one of the reasons VarCodeGen is
358	     *  structured this way in the first place.
359	     */
360	    public static class LocalVar extends StackVar {

360	    public static class LocalVar extends StackVar {
361	        public LocalVar(IdOrOp name, Type fortressType, CodeGen cg) {
362	            super(name, fortressType, cg);
363	        }
364	
365	        public String toString() {
366	            return "VarCodeGen[localVar] " + name + ":" + fortressType;
367	        }
368	
369	    }
