371	    public static class LocalMutableVar extends VarCodeGen {
372	        // LocalMutableVar's must be MutableFValues
373	        int offset;
374	        public final String name;
375	        public final Type fortressType;
376	        private final APIName ifNone;
377	
378	
379	        public LocalMutableVar(IdOrOp id, Type fortressType, CodeGen cg, APIName ifNone) {
380	            super(id.getText(), fortressType);
381	            this.name = id.getText();
382	            this.fortressType = fortressType;
383	            this.offset = cg.mv.createCompilerLocal(name, NamingCzar.descFortressMutableFValueInternal);
384	            this.ifNone = ifNone;
385	            cg.mv.visitTypeInsn(Opcodes.NEW, "com/sun/fortress/compiler/runtimeValues/MutableFValue");
386	            cg.mv.visitInsn(Opcodes.DUP);
387	            cg.mv.visitMethodInsn(Opcodes.INVOKESPECIAL,
388	                                  "com/sun/fortress/compiler/runtimeValues/MutableFValue",
389	                                  "<init>",
390	                                  "()V");
391	            cg.mv.visitVarInsn(Opcodes.ASTORE, offset);
392	        }
393	
394	        // For Debugging
395	        public void printString(CodeGenMethodVisitor mv, String s) {
396	            mv.visitFieldInsn(Opcodes.GETSTATIC, "java/lang/System", "out", "Ljava/io/PrintStream;");
397	            mv.visitLdcInsn(s);
398	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/io/PrintStream", "println", "(Ljava/lang/String;)V");
399	        }
400	    
401	        public void assignValue(CodeGenMethodVisitor mv) {
402	            Label atomicEnd = new Label();
403	            Label end = new Label();
404	            
405	            mv.visitMethodInsn(Opcodes.INVOKESTATIC, 
406	                               "com/sun/fortress/runtimeSystem/BaseTask",
407	                               "inATransaction",
408	                               "()Z");
409	            mv.visitJumpInsn(Opcodes.IFEQ, atomicEnd);
410	            mv.visitMethodInsn(Opcodes.INVOKESTATIC,
411	                               "com/sun/fortress/runtimeSystem/BaseTask",
412	                               "getCurrentTransaction",
413	                               "()Lcom/sun/fortress/runtimeSystem/Transaction;");
414	            mv.visitInsn(Opcodes.SWAP);            
415	            mv.visitVarInsn(Opcodes.ALOAD, offset);
416	            mv.visitInsn(Opcodes.SWAP);    
417	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,
418	                               "com/sun/fortress/runtimeSystem/Transaction",
419	                               "TXWrite",
420	                               "(Lcom/sun/fortress/compiler/runtimeValues/MutableFValue;Lcom/sun/fortress/compiler/runtimeValues/FValue;)V");
421	            mv.visitJumpInsn(Opcodes.GOTO, end);
422	            mv.visitLabel(atomicEnd);
423	            mv.visitVarInsn(Opcodes.ALOAD, offset);
424	            mv.visitInsn(Opcodes.SWAP);
425	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, 
426	                               "com/sun/fortress/compiler/runtimeValues/MutableFValue", 
427	                               "setValue",
428	                               "(Lcom/sun/fortress/compiler/runtimeValues/FValue;)V");
429	            mv.visitLabel(end);
430	        }
431	
432	        public void assignHandle(CodeGenMethodVisitor mv) {
433	            mv.visitVarInsn(Opcodes.ASTORE, offset);
434	        }
435	
436	        public void pushHandle(CodeGenMethodVisitor mv) {
437	            mv.visitVarInsn(Opcodes.ALOAD, offset);
438	        }
439	
440	        public void pushValue(CodeGenMethodVisitor mv) {
441	            Label atomicEnd = new Label();
442	            Label end = new Label();
443	            mv.visitMethodInsn(Opcodes.INVOKESTATIC, 
444	                               "com/sun/fortress/runtimeSystem/BaseTask",
445	                               "inATransaction",
446	                               "()Z");
447	            mv.visitJumpInsn(Opcodes.IFEQ, atomicEnd);
448	            mv.visitMethodInsn(Opcodes.INVOKESTATIC,
449	                               "com/sun/fortress/runtimeSystem/BaseTask",
450	                               "getCurrentTransaction",
451	                               "()Lcom/sun/fortress/runtimeSystem/Transaction;");
452	            mv.visitVarInsn(Opcodes.ALOAD, offset);
453	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,
454	                               "com/sun/fortress/runtimeSystem/Transaction",
455	                               "TXRead",
456	                               "(Lcom/sun/fortress/compiler/runtimeValues/MutableFValue;)Lcom/sun/fortress/compiler/runtimeValues/FValue;");
457	
458	            mv.visitJumpInsn(Opcodes.GOTO, end);
459	            mv.visitLabel(atomicEnd);
460	
461	            
462	            mv.visitVarInsn(Opcodes.ALOAD, offset);
463	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "com/sun/fortress/compiler/runtimeValues/MutableFValue", 
464	                               "getValue",
465	                               "()Lcom/sun/fortress/compiler/runtimeValues/FValue;");
466	            mv.visitLabel(end);
467	            mv.visitTypeInsn(Opcodes.CHECKCAST, NamingCzar.jvmTypeDesc(fortressType, ifNone, false));
468	        }
469	
470	        public String toString() {
471	            return "VarCodeGen[localMutableVar] " + name + ":" + fortressType;
472	        }
473	
474	        public void outOfScope(CodeGenMethodVisitor mv) {
475	            mv.disposeCompilerLocal(offset);
476	        }
477	    }
