479	    public static class TaskVarCodeGen extends VarCodeGen {
480	        final String taskClass;
481	        private final APIName ifNone;
482	
483	        public TaskVarCodeGen(VarCodeGen v, String taskClass, APIName ifNone, ClassVisitor cw) {
484	            super(v.name, v.fortressType);
485	            this.taskClass = taskClass;
486	            this.ifNone = ifNone;
487	            Debug.debug(Debug.Type.CODEGEN, 1,
488	                        "Creating a new TaskVarCodeGen from VarCodeGen " + v);
489	
490	            cw.visitField(Opcodes.ACC_PUBLIC + Opcodes.ACC_FINAL, v.name,
491	                          NamingCzar.jvmBoxedTypeDesc(v.fortressType, ifNone),
492	                          null, null);
493	        }
494	
495	        public TaskVarCodeGen(IdOrOp name, Type fortressType, String taskClass, APIName ifNone, ClassVisitor cw) {
496	            super(name, fortressType);
497	            this.ifNone = ifNone;
498	            this.taskClass = taskClass;
499	            cw.visitField(Opcodes.ACC_PUBLIC + Opcodes.ACC_FINAL, name.getText(),
500	                          NamingCzar.jvmBoxedTypeDesc(fortressType, ifNone),
501	                          null, null);
502	        }
503	
504	        public void pushValue(CodeGenMethodVisitor mv) {
505	            mv.visitVarInsn(Opcodes.ALOAD, mv.getThis());
506	            mv.visitFieldInsn(Opcodes.GETFIELD, taskClass,
507	                              getName(),
508	                              NamingCzar.jvmBoxedTypeDesc(fortressType, ifNone)) ;
509	
510	        }
511	
512	        public void assignValue(CodeGenMethodVisitor mv) {
513	            mv.visitVarInsn(Opcodes.ALOAD, mv.getThis());
514	            mv.visitInsn(Opcodes.SWAP);
515	            mv.visitFieldInsn(Opcodes.PUTFIELD, taskClass,
516	                              getName(),
517	                              NamingCzar.jvmBoxedTypeDesc(fortressType, ifNone)
518	                              );
519	//            mv.visitMethodInsn(Opcodes.INVOKESTATIC, NamingCzar.internalFortressVoid, NamingCzar.make,
520	//                           Naming.makeMethodDesc("", NamingCzar.descFortressVoid));
521	        }
522	
523	        public void outOfScope(CodeGenMethodVisitor mv) {
524	            // We've already told asm about our type and such.
525	        }
526	
527	    }
