529	    public static class MutableTaskVarCodeGen extends VarCodeGen {
530	        final String taskClass;
531	        private final APIName ifNone;
532	
533	        public MutableTaskVarCodeGen(LocalMutableVar lmv, String taskClass, APIName ifNone, 
534	                                     ClassVisitor cw, CodeGenMethodVisitor mv) {
535	            super(lmv.name, lmv.fortressType);
536	            this.taskClass = taskClass;
537	            this.ifNone = ifNone;
538	
539	            cw.visitField(Opcodes.ACC_PUBLIC + Opcodes.ACC_FINAL, lmv.name,
540	                          "Lcom/sun/fortress/compiler/runtimeValues/MutableFValue;",
541	                          null, null);
542	        }
543	
544	        public MutableTaskVarCodeGen(MutableTaskVarCodeGen mtvcg, String taskClass, APIName ifNone,
545	                                     ClassVisitor cw, CodeGenMethodVisitor mv) {
546	            super(mtvcg.name, mtvcg.fortressType);
547	            this.taskClass = taskClass;
548	            this.ifNone = ifNone;
549	            cw.visitField(Opcodes.ACC_PUBLIC + Opcodes.ACC_FINAL, mtvcg.name,
550	                          "Lcom/sun/fortress/compiler/runtimeValues/MutableFValue;",
551	                          null, null);
552	        }
553	
554	        public void assignHandle(CodeGenMethodVisitor mv) {
555	            mv.visitVarInsn(Opcodes.ALOAD, mv.getThis());
556	            mv.visitInsn(Opcodes.SWAP);
557	            mv.visitFieldInsn(Opcodes.PUTFIELD, taskClass, getName(), 
558	                               "Lcom/sun/fortress/compiler/runtimeValues/MutableFValue;");
559	        }
560	
561	        public void assignValue(CodeGenMethodVisitor mv) {
562	            Label atomicEnd = new Label();
563	            Label end = new Label();
564	            
565	            mv.visitMethodInsn(Opcodes.INVOKESTATIC, 
566	                               "com/sun/fortress/runtimeSystem/BaseTask",
567	                               "inATransaction",
568	                               "()Z");
569	            mv.visitJumpInsn(Opcodes.IFEQ, atomicEnd);
570	            mv.visitMethodInsn(Opcodes.INVOKESTATIC,
571	                               "com/sun/fortress/runtimeSystem/BaseTask",
572	                               "getCurrentTransaction",
573	                               "()Lcom/sun/fortress/runtimeSystem/Transaction;");
574	            mv.visitInsn(Opcodes.SWAP);            
575	            mv.visitVarInsn(Opcodes.ALOAD, mv.getThis());
576	            mv.visitFieldInsn(Opcodes.GETFIELD, taskClass,
577	                              getName(),
578	                              "Lcom/sun/fortress/compiler/runtimeValues/MutableFValue;");       
579	            mv.visitInsn(Opcodes.SWAP);
580	            mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,
581	                               "com/sun/fortress/runtimeSystem/Transaction",
582	                               "TXWrite",
583	                               "(Lcom/sun/fortress/compiler/runtimeValues/MutableFValue;Lcom/sun/fortress/compiler/runtimeValues/FValue;)V");
584	            mv.visitJumpInsn(Opcodes.GOTO, end);
