26	/** Base class for Fortress tasks.  Includes administrative methods
27	 *  that make code generation for task spawn a bit easier.
28	 *
29	 *  We shy away from the "easiest thing of all": forking in the constructor.
30	 *  Given the plethora of final fields in the usual Fortress task, such a step
31	 *  would be a memory model disaster!  Instead, we generate code like:
32	 *    Fib$task0 tmp = new Fib$task0(arg);
33	 *    tmp.forkIfProfitable();
34	 *    ... other code ...
35	 *    tmp.joinOrRun();
36	 *    ... use tmp.result (compiler-inserted field) if desired ...
37	 */
38	public abstract class BaseTask extends FortressExecutable {
39	    // Could get this by hacking ForkJoinTask's status field, but
40	    // not touching that for now as it's too changeable
41	    private static final int UNFORKED = 0;
42	    private static final int FORKED = 1;
43	    private static final int EXECUTED = 2;
44	    private int actuallyForked = UNFORKED;
45	
46	    BaseTask parent;
47	    Transaction transaction;
48	    private static Random gen = new Random();
49	
50	    private static Boolean debug = false;
51	
